// Build the shared envelope from whichever trigger fired.
// Demo: single client, so client_id is fixed to 'demo_client'. In production the
// client_id is derived from which reseller/inbox forwarded the RFQ.
const t = $input.first().json;
const subject = t.subject || 'RFQ';
const text = t.text || t.chatInput || t.body || '';
return [{ json: { client_id: 'demo_client', data: { subject, text } } }];

// Resolve client_config ONCE from the registry. Passed through to every module so they
// skip their own Notion lookup (resolve-once). Also checks the client is active.
const env = $('Build Envelope').first().json;
const wantId = env.client_id;
const rows = $input.all();
function prop(props, name){ const p = props && props[name]; if(!p) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);
const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  status: prop(match,'Client Status'),
  plan_tier: prop(match,'plan_tier'),
  modules: {
    data_collection: !!prop(match,'module_data_collection'),
    content_generation: !!prop(match,'module_content_generation'),
    pricing: !!prop(match,'module_pricing'),
    proposal_assembly: !!prop(match,'module_proposal_assembly')
  },
  commercial_contact_email: prop(match,'commercial_contact_email'),
  templates: { en: prop(match,'template_id_en'), es: prop(match,'template_id_es') },
  proposals_folder_id: prop(match,'proposals_folder_id'),
  reference_docs_folder_id: prop(match,'reference_docs_folder_id'),
  notification_chat_id: prop(match,'notification_chat_id')
};
return [{ json: { client_id: wantId, client_config, data: env.data, status: 'ok', errors: [] } }];

// Manual pricing estimate. Phase 1 has NO automatic hours-estimation engine (explicit
// non-goal): in production a human enters materials_cost + hours per category per RFQ.
// The demo injects a representative estimate so the pipeline runs end-to-end.
return [{ json: {
  client_id: $json.client_id,
  client_config: $json.client_config,
  data: { materials_cost: 5000, hours_by_category: { engineering: 40, assembly: 60, commissioning: 20, project_management: 15 } }
} }];

// Compose the Module 4 (assembly) input from the three module outputs.
const m1 = $('Call Module 1').first().json;
const m2 = $('Call Module 2').first().json;
const m3 = $('Call Module 3').first().json;
return [{ json: {
  client_id: m1.client_id,
  client_config: m1.client_config || null,
  status: 'ok',
  errors: [],
  data: { rfq: m1.data, content: m2.data, pricing: m3.data }
} }];

